<script lang="ts">
  import { onMount, tick } from "svelte";
  import Icon from "./Icon.svelte";
  import Wordmark from "./Wordmark.svelte";
  import { app } from "./store.svelte";
  import { version } from "../../src-tauri/tauri.conf.json";

  // About ShredLab. Opened from Settings (app.openAbout()). "Third-party licenses" shows
  // THIRD_PARTY_LICENSES.html, generated by tools/third_party_licenses/generate.mjs into
  // app/public, so it is part of the bundled UI (works offline, in the mock and in release).

  const LICENSES_URL = "/THIRD_PARTY_LICENSES.html";

  let showLicenses = $state(false);
  let closeBtn: HTMLButtonElement;
  let backBtn = $state<HTMLButtonElement>();
  let licensesBtn = $state<HTMLButtonElement>();

  async function setLicenses(on: boolean) {
    showLicenses = on;
    await tick();
    (on ? backBtn : licensesBtn)?.focus();
  }

  function onKey(e: KeyboardEvent) {
    if (e.key !== "Escape") return;
    if (showLicenses) setLicenses(false);
    else app.closeAbout();
  }

  onMount(() => closeBtn.focus());
</script>

<svelte:window onkeydown={onKey} />

<div class="backdrop" role="presentation" onclick={(e) => e.target === e.currentTarget && app.closeAbout()}>
  <div class="dialog" class:wide={showLicenses} role="dialog" aria-modal="true" aria-labelledby="about-title">
    <div class="head">
      {#if showLicenses}
        <button class="btn ghost small" bind:this={backBtn} onclick={() => setLicenses(false)}>← About</button>
        <h2 id="about-title">Third-party licenses</h2>
      {:else}
        <h2 id="about-title">About ShredLab</h2>
      {/if}
      <button class="btn ghost small icon-only" bind:this={closeBtn} onclick={() => app.closeAbout()} aria-label="Close"><Icon name="close" size={14} /></button>
    </div>

    {#if showLicenses}
      <iframe class="licenses" src={LICENSES_URL} title="Third-party licenses"></iframe>
    {:else}
      <div class="about">
        <div class="brand"><Wordmark size={34} /></div>
        <p class="version">Version {version}{__SHREDLAB_COMMIT__ ? ` (${__SHREDLAB_COMMIT__})` : ""}</p>
        <p>Copyright (C) 2026 Navneet Joneja</p>
        <p class="small">
          ShredLab is free software under the GNU General Public License, version 3 or (at your option) any later version,
          with an additional permission for Microsoft DirectML. It comes with absolutely no warranty. Bundled components and
          models keep their own licenses.
        </p>
        <p class="small muted">
          “ShredLab” and the ShredLab logo are trademarks of Navneet Joneja. The GPL covers the code, not the name or the logo.
        </p>
        <button class="btn" bind:this={licensesBtn} onclick={() => setLicenses(true)}>Third-party licenses</button>
      </div>
    {/if}
  </div>
</div>

<style>
  .backdrop {
    position: fixed;
    inset: 0;
    z-index: 60;
    background: var(--backdrop);
    display: grid;
    place-items: center;
    padding: 20px;
  }
  .dialog {
    width: 440px;
    max-width: 100%;
    max-height: calc(100vh - 40px);
    display: flex;
    flex-direction: column;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 16px 18px;
    box-shadow: var(--shadow);
  }
  .dialog.wide {
    width: 900px;
    height: calc(100vh - 40px);
  }
  .head {
    display: flex;
    gap: 8px;
    align-items: center;
    margin-bottom: 8px;
  }
  .head h2 {
    flex: 1;
  }
  h2 {
    margin: 0;
    font-size: 17px;
  }
  .about {
    text-align: center;
    padding: 4px 8px 6px;
  }
  .brand {
    color: var(--accent);
    margin: 6px 0 2px;
  }
  .version {
    color: var(--muted);
    margin: 0 0 10px;
    font-size: 12.5px;
  }
  .about p {
    margin: 0 0 10px;
    line-height: 1.45;
  }
  .small {
    font-size: 12.5px;
  }
  .licenses {
    flex: 1;
    width: 100%;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: var(--surface-2);
  }
</style>
